package io.rift.cronos;
import org.junit.Test;import org.json.*;import java.io.*;import static org.junit.Assert.*;
public final class HoldingsCheckTest {
 static final String OWNER="0x"+"a".repeat(40),OTHER="0x"+"b".repeat(40),HASH="0x"+"c".repeat(64);static JSONArray rows()throws Exception{return new JSONArray().put(new JSONObject().put("contract",OTHER).put("standard","ERC-721").put("tokenId","1"));}
 static class Rpc implements TransferDiscovery.Rpc {int anchors,calls;boolean reorg,fail,wrong,malformed;String raw="0x"+"0".repeat(24)+OWNER.substring(2);public void requireCronos()throws Exception{if(wrong)throw new IOException();}public Object call(String op,JSONArray params)throws Exception{calls++;if(op.equals("eth_blockNumber"))return "0x64";if(op.equals("eth_getBlockByNumber")){anchors++;return new JSONObject().put("number","0x64").put("hash",reorg&&anchors>1?"0x"+"d".repeat(64):HASH);}assertEquals("eth_call",op);assertEquals(HASH,params.getJSONObject(1).getString("blockHash"));assertTrue(params.getJSONObject(1).getBoolean("requireCanonical"));assertEquals(OTHER,params.getJSONObject(0).getString("to"));if(fail)throw new IOException("unsupported EIP1898");return malformed?"0x":raw;}}
 @Test public void positiveAndSentAwayAreObservedAtSamePinnedHash()throws Exception{Rpc rpc=new Rpc();JSONObject v=HoldingsCheck.read(rpc,OWNER,rows(),()->{});assertEquals("1",v.getJSONArray("results").getJSONObject(0).getString("amount"));assertEquals(2,rpc.anchors);rpc=new Rpc();rpc.raw="0x"+"0".repeat(24)+OTHER.substring(2);assertEquals("0",HoldingsCheck.read(rpc,OWNER,rows(),()->{}).getJSONArray("results").getJSONObject(0).getString("amount"));}
 @Test public void uint256BalancesNeverUseFloatingPoint()throws Exception{Rpc rpc=new Rpc();rpc.raw="0x"+"f".repeat(64);JSONArray r=rows();r.getJSONObject(0).put("standard","ERC-1155").put("tokenId",new java.math.BigInteger("f".repeat(64),16).toString());assertEquals(new java.math.BigInteger("f".repeat(64),16).toString(),HoldingsCheck.read(rpc,OWNER,r,()->{}).getJSONArray("results").getJSONObject(0).getString("amount"));}
 @Test public void failuresNeverYieldZeroOrPartialSuccess()throws Exception{for(int i=0;i<5;i++){Rpc rpc=new Rpc();rpc.reorg=i==0;rpc.fail=i==1;rpc.wrong=i==2;rpc.malformed=i==3;if(i==4)rpc.raw="0x"+"f".repeat(64);try{HoldingsCheck.read(rpc,OWNER,rows(),()->{});fail();}catch(IOException expected){}}}
 @Test public void inputBoundsAndDuplicatesFailBeforeNetwork()throws Exception{for(int i=0;i<5;i++){JSONArray r=rows();if(i==0)r=new JSONArray();if(i==1)for(int n=0;n<12;n++)r.put(new JSONObject(r.getJSONObject(0).toString()).put("tokenId",String.valueOf(n+2)));if(i==2)r.put(r.getJSONObject(0));if(i==3)r.getJSONObject(0).put("endpoint","https://bad.example");if(i==4)r.getJSONObject(0).put("standard","ERC-20");Rpc rpc=new Rpc();try{HoldingsCheck.read(rpc,OWNER,r,()->{});fail();}catch(IllegalArgumentException expected){}assertEquals(0,rpc.calls);}}
 @Test public void cancellationStopsBeforeNextRpc()throws Exception{Rpc rpc=new Rpc();int[] check={0};try{HoldingsCheck.read(rpc,OWNER,rows(),()->{if(++check[0]==2)throw new IOException("cancelled");});fail();}catch(IOException expected){}assertEquals(2,rpc.calls);}
 @Test public void twelveEntriesAreAcceptedOnlyAsWholePage()throws Exception{JSONArray r=rows();for(int n=2;n<=12;n++)r.put(new JSONObject(r.getJSONObject(0).toString()).put("tokenId",String.valueOf(n)));assertEquals(12,HoldingsCheck.read(new Rpc(),OWNER,r,()->{}).getJSONArray("results").length());}
 @Test public void calldataIsFixedByStandardAndUint256Input()throws Exception{Rpc rpc=new Rpc(){@Override public Object call(String op,JSONArray p)throws Exception{if(op.equals("eth_call"))assertEquals("0x6352211e"+"0".repeat(63)+"1",p.getJSONObject(0).getString("data"));return super.call(op,p);}};HoldingsCheck.read(rpc,OWNER,rows(),()->{});Rpc multi=new Rpc(){@Override public Object call(String op,JSONArray p)throws Exception{if(op.equals("eth_call"))assertEquals("0x00fdd58e"+"0".repeat(24)+OWNER.substring(2)+"0".repeat(63)+"1",p.getJSONObject(0).getString("data"));return super.call(op,p);}};JSONArray r=rows();r.getJSONObject(0).put("standard","ERC-1155");HoldingsCheck.read(multi,OWNER,r,()->{});}
 @Test public void sourceChangeAtFinalCheckRejectsOtherwiseValidPage()throws Exception{int[] n={0};try{HoldingsCheck.read(new Rpc(),OWNER,rows(),()->{if(++n[0]==4)throw new IOException("source changed");});fail();}catch(IOException expected){assertEquals(4,n[0]);}}

}
